import numpy as np
import matplotlib.pyplot as plt

def sum_natural_numbers(n):
    if n == 1:
        return 1
    else:
        return n + sum_natural_numbers(n-1)

n = 10
sum_series = []
for i in range(1, n+1):
    sum_series.append(sum_natural_numbers(i))

plt.bar(range(1, n+1), sum_series)
plt.xlabel('Natural Numbers')
plt.ylabel('Sum')
plt.title('Cumulative Sum of Natural Numbers')
plt.show()

